        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other' GROUP BY ALL UNION ALL SELECT service_name, span_name, count(*), round(avg(duration)/1e6,1) FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other' GROUP BY ALL",
